import { ArrowUp } from 'lucide-react'
import type { ReactNode } from 'react'
import { useEffect, useState } from 'react'

import { cx } from '~/lib/cx'

import styles from './float-button.module.scss'

export type FloatButtonPosition =
  | 'bottom-right'
  | 'bottom-left'
  | 'top-right'
  | 'top-left'

const POSITION = {
  'bottom-right': styles.bottomRight,
  'bottom-left': styles.bottomLeft,
  'top-right': styles.topRight,
  'top-left': styles.topLeft,
} as const

export type FloatButtonSize = 'sm' | 'md' | 'lg'

export interface FloatButtonProps {
  icon?: ReactNode
  label?: string
  description?: string
  badge?: string | number
  position?: FloatButtonPosition
  size?: FloatButtonSize
  shape?: 'circle' | 'square'
  /** Render inside a positioned parent instead of the viewport. */
  contained?: boolean
  /** Scroll to the top when clicked. */
  backToTop?: boolean
  /** Show after this scroll offset. Defaults to 0 (always visible). */
  visibleAfter?: number
  disabled?: boolean
  onClick?: () => void
  className?: string
  'aria-label'?: string
}

/** Floating action button, optionally doubling as a back-to-top control. */
export function FloatButton({
  icon,
  label,
  description,
  badge,
  position = 'bottom-right',
  size = 'md',
  shape = 'circle',
  contained = false,
  backToTop = false,
  visibleAfter = 0,
  disabled = false,
  onClick,
  className,
  'aria-label': ariaLabel,
}: FloatButtonProps) {
  const [visible, setVisible] = useState(visibleAfter <= 0)

  useEffect(() => {
    if (visibleAfter <= 0) {
      setVisible(true)
      return
    }
    const update = () => setVisible(window.scrollY >= visibleAfter)
    update()
    window.addEventListener('scroll', update, { passive: true })
    return () => window.removeEventListener('scroll', update)
  }, [visibleAfter])

  const content = icon ?? (backToTop ? <ArrowUp aria-hidden size={18} /> : null)
  const name = ariaLabel ?? label ?? (backToTop ? 'Back to top' : 'Actions')

  return (
    <div
      className={cx(
        styles.root,
        POSITION[position],
        contained && styles.contained,
        !visible && styles.hidden,
        className,
      )}
    >
      {description ? <p className={styles.description}>{description}</p> : null}
      <button
        type="button"
        className={cx(
          styles.button,
          size === 'sm' && styles.sm,
          size === 'lg' && styles.lg,
          shape === 'square' && styles.square,
          label && styles.extended,
        )}
        aria-label={name}
        disabled={disabled}
        onClick={() => {
          if (backToTop) window.scrollTo({ top: 0, behavior: 'smooth' })
          onClick?.()
        }}
      >
        {content}
        {label ? <span className={styles.label}>{label}</span> : null}
        {badge != null ? <span className={styles.badge}>{badge}</span> : null}
      </button>
    </div>
  )
}

@use 'styles' as vz;

.root {
  position: fixed;
  z-index: var(--z-toast);
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: vz.space(2);
}

.contained {
  position: absolute;
  inset: auto var(--float-inset, #{vz.space(4)}) var(--float-inset, #{vz.space(4)}) auto;
}

.bottom-right {
  right: var(--float-inset, #{vz.space(6)});
  bottom: var(--float-inset, #{vz.space(6)});
}

.bottom-left {
  left: var(--float-inset, #{vz.space(6)});
  bottom: var(--float-inset, #{vz.space(6)});
  align-items: flex-start;
}

.top-right {
  right: var(--float-inset, #{vz.space(6)});
  top: var(--float-inset, #{vz.space(6)});
}

.top-left {
  left: var(--float-inset, #{vz.space(6)});
  top: var(--float-inset, #{vz.space(6)});
  align-items: flex-start;
}

.button {
  position: relative;
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: vz.space(2);
  width: var(--float-size, #{vz.space(12)});
  height: var(--float-size, #{vz.space(12)});
  padding: 0;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('full');
  background: vz.color('card');
  color: vz.color('foreground');
  box-shadow: vz.elevation(3);
  cursor: pointer;
  transition:
    transform vz.duration('fast') vz.ease('out'),
    box-shadow vz.duration('base') vz.ease('out'),
    background-color vz.duration('base') vz.ease('out');

  @include vz.hover {
    background: vz.color('accent');
    box-shadow: vz.elevation(3);
  }

  @include vz.active {
    transform: scale(0.96);
  }

  @include vz.focus-ring(2px, 3px, 0.7);

  &:disabled {
    opacity: 0.5;
    pointer-events: none;
  }
}

.square {
  border-radius: var(--radius-lg);
}

.sm {
  --float-size: #{vz.space(10)};
}

.lg {
  --float-size: #{vz.space(14)};
}

.extended {
  width: auto;
  padding-inline: vz.space(4);
}

.label {
  font-size: vz.font-size('xs');
  font-weight: 600;
}

.description {
  display: block;
  margin: 0;
  max-width: 14rem;
  padding: vz.space(2) vz.space(3);
  border: 1px solid vz.color('border');
  border-radius: var(--radius-lg);
  background: vz.color('popover');
  color: vz.color('popover-foreground');
  box-shadow: vz.elevation(2);
  font-size: vz.font-size('xs');
  line-height: 1.5;
}

.badge {
  position: absolute;
  top: -2px;
  right: -2px;
  min-width: 1.125rem;
  height: 1.125rem;
  padding: 0 vz.space(1);
  border: 2px solid vz.color('card');
  border-radius: vz.radius('full');
  background: vz.color('destructive');
  color: vz.color('destructive-foreground');
  font-size: 0.625rem;
  font-weight: 700;
  line-height: 1;
  display: grid;
  place-items: center;
}

.hidden {
  display: none;
}
